<?php use VO\Support\Template; ob_start(); ?>
<h1>Pedido <?= Template::e($order['number']) ?></h1><section class="card"><p><strong>Estado:</strong> <?= Template::e($order['status']) ?> · <strong>Sucursal:</strong> <?= Template::e($order['branch_name']) ?></p><p><strong>Contacto:</strong> <?= Template::e($order['customer_name'] ?? '') ?> · <?= Template::e($order['customer_phone'] ?? '') ?> · <?= Template::e($order['customer_email'] ?? '') ?></p><p><strong>Total:</strong> $ <?= number_format(((int)$order['grand_total_cents'])/100,2,',','.') ?></p></section>
<section class="card"><h2>Ítems</h2><?php foreach ($items as $i): ?><p><?= (int)$i['quantity'] ?> × <?= Template::e($i['item_name']) ?> <?= Template::e($i['variant_name'] ?? '') ?> · $ <?= number_format(((int)$i['line_total_cents'])/100,2,',','.') ?></p><?php foreach ($i['modifiers'] as $m): ?><p class="muted">+ <?= Template::e($m['group_name']) ?>: <?= Template::e($m['modifier_name']) ?></p><?php endforeach; endforeach; ?></section>
<?php if ($address): ?><section class="card"><h2>Dirección</h2><p><?= Template::e($address['recipient_name'] ?? '') ?> · <?= Template::e($address['street'] ?? '') ?> · <?= Template::e($address['city'] ?? '') ?> · <?= Template::e($address['notes'] ?? '') ?></p></section><?php endif; ?>
<section class="card"><h2>Descuentos</h2><?php foreach ($discounts as $d): ?><p><?= Template::e($d['kind']) ?> <?= Template::e($d['code'] ?? '') ?> · $ <?= number_format(((int)$d['amount_cents'])/100,2,',','.') ?></p><?php endforeach; if (!$discounts): ?><p>Sin descuentos.</p><?php endif; ?></section>
<section class="card"><h2>Totales</h2><p>Productos: $ <?= number_format(((int)$order['gross_items_cents'])/100,2,',','.') ?> · Mercadería: $ <?= number_format(((int)$order['merchandise_total_cents'])/100,2,',','.') ?> · Envío: $ <?= number_format(((int)$order['delivery_fee_cents'])/100,2,',','.') ?></p></section>
<section class="card"><h2>Movimientos de stock</h2><?php foreach ($movements as $m): ?><p><?= Template::e($m['reason']) ?> · <?= (int)$m['quantity_delta'] ?> · item <?= (int)$m['item_id'] ?></p><?php endforeach; if (!$movements): ?><p>Sin movimientos.</p><?php endif; ?></section>
